#ifndef BONFYRE_SOURCE_DESK_H
#define BONFYRE_SOURCE_DESK_H
static int session_institution_authorized(const char *,const char *,const char *,const char *);
/* Native structure shared by Links and source intake; domain owners keep all state. */
static void source_desk_head(void){fputs("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Links and sources · Aurekai</title><link rel=\"stylesheet\" href=\"/assets/aurekai-native.css?v=2\"><link rel=\"stylesheet\" href=\"/apps/source-desk.css\">",stdout);bf_route_presentation_emit_head(stdout,"connections");fputs("</head>",stdout);}
static void source_desk_content(void){fputs("<main class=\"source-desk\" data-source-desk><nav class=\"sd-breadcrumbs\" aria-label=\"Breadcrumb\"><a href=\"/\">Aurekai</a><span aria-hidden=\"true\">/</span><span>Links and sources</span></nav><header class=\"sd-heading\"><div><p class=\"sd-eyebrow\">From the internet to your work</p><h1>Find a source.<br>Work with its contents.</h1><p>Browse the sources Aurekai already knows, inspect retained passages, and prepare a research review in your own workspace.</p></div><nav aria-label=\"Continue your work\"><a href=\"/apps?context=self\">Your work</a><a href=\"/s/sets/all\">Source collections</a></nav></header><div class=\"sd-mode-tabs\" aria-label=\"How to start\"><button type=\"button\" data-mode=\"browse\">Browse known sources</button><button type=\"button\" data-mode=\"address\">Bring a web address</button></div><section data-mode-panel=\"address\"><form class=\"sd-address-form\" action=\"/studio/\" method=\"get\"><label for=\"sd-url\">Page or feed address</label><p id=\"sd-url-help\">Paste a complete public address. Reviewing it here does not fetch, connect, or publish anything.</p><div class=\"sd-input-action\"><input id=\"sd-url\" name=\"foreign_url\" type=\"url\" required autocomplete=\"url\" placeholder=\"https://publisher.example/article\" aria-describedby=\"sd-url-help\"><button type=\"submit\">Review this address</button></div><div data-address-preview aria-live=\"polite\"></div></form></section><section data-mode-panel=\"browse\"><form class=\"sd-search\" action=\"/link\" method=\"get\"><label for=\"sd-query\">Search sources already known to Aurekai</label><div class=\"sd-input-action\"><input id=\"sd-query\" name=\"q\" type=\"search\" maxlength=\"240\" placeholder=\"Publisher, topic, source name, or hostname\"><button type=\"submit\">Find sources</button></div><p>This searches the local source catalogue, not the whole web.</p></form><div class=\"sd-catalogue-bar\"><p data-catalogue-status role=\"status\" aria-live=\"polite\">Opening the source catalogue…</p><button type=\"button\" data-catalogue-retry hidden>Retry catalogue</button><button type=\"button\" data-source-commands>Commands</button></div><div data-source-collection></div><button type=\"button\" data-more-sources hidden>Load more sources</button></section><noscript><p>The source explorer needs JavaScript. The address-review form and <a href=\"/apps?context=self\">your installed work</a> remain available.</p></noscript></main><script type=\"module\" src=\"/apps/source-desk.mjs\"></script>",stdout);}
static int serve_source_desk(const char *method,const char *target,const char *accept){
 if(strcmp(method,"GET")||!wants_html(accept))return 0;
 if(strcmp(target,"/sources")&&strcmp(target,"/sources/")&&strcmp(target,"/foreign/workbench")&&strcmp(target,"/foreign/workbench/")&&strcmp(target,"/s/work/foreign-twins")&&strcmp(target,"/s/work/foreign-twins/"))return 0;
 fputs("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nCache-Control: private, no-store\r\nVary: Host, Accept, Cookie, Authorization\r\nX-Bonfyre-Surface-Program: native-source-workspace\r\nConnection: close\r\n\r\n",stdout);source_desk_head();fputs("<body data-aurekai-pattern=\"connections\">",stdout);fputs(BF_ESTATE_BAR,stdout);source_desk_content();if(session_institution_authorized(page_request_bearer,page_request_auth_db,"bonfyre","admin"))fputs("<aside style=\"max-width:1100px;margin:18px auto 45px;padding:12px 22px\"><a href=\"/sources/push\">WebSub delivery operations</a> · Administer retained lease, challenge, delivery and observation standing</aside>",stdout);fputs("</body></html>",stdout);return 1;
}
#endif
